"Übungsmodus: Jeder Schritt zeigt, welche Formel du in welcher Reihenfolge anwendest – die Zahlenwerte sind als „…“ ausgeblendet. Rechne selbst, prüfe dein Ergebnis in den Karten unten oder decke Schritt für Schritt auf.":"Mode exercice : chaque étape indique quelle formule appliquer et dans quel ordre – les valeurs sont masquées par « … ». Calcule toi-même, contrôle ton résultat dans les cartes ci-dessous ou dévoile les étapes une à une.",
