"Hinterlüftete Außenschale: {} entfallen (Diffusion und Wärme), R<sub>se</sub> = 0,08 m²K/W":"Paroi extérieure ventilée : {} négligées (diffusion et chaleur), R<sub>se</sub> = 0,08 m²K/W",
"R<sub>T</sub> = ½·R<sub>T,u</sub> + ½·R<sub>T,v</sub> = {} m²K/W → gleichwertig R<sub>Luft</sub> = {} m²K/W":"R<sub>T</sub> = ½·R<sub>T,u</sub> + ½·R<sub>T,v</sub> = {} m²K/W → équivalent R<sub>air</sub> = {} m²K/W",
"ruhend gerechnet R<sub>T,u</sub> = {} · stark belüftet gerechnet R<sub>T,v</sub> = {} m²K/W":"calculée non ventilée R<sub>T,u</sub> = {} · calculée fortement ventilée R<sub>T,v</sub> = {} m²K/W",
"Schwach belüftete Luftschicht (DIN EN ISO 6946, 6.9.3, A_v ≈ 1000 mm² je m)":"Lame d’air faiblement ventilée (EN ISO 6946, 6.9.3, A_v ≈ 1000 mm² par m)",
"Die Luftschicht und alle Schichten außerhalb entfallen ({}); außen gilt ruhende Luft: R<sub>se</sub> = R<sub>si</sub> = {} m²K/W":"La lame d’air et toutes les couches extérieures sont négligées ({}) ; à l’extérieur, air calme : R<sub>se</sub> = R<sub>si</sub> = {} m²K/W",
"Stark belüftete Luftschicht (DIN EN ISO 6946, 6.9.4)":"Lame d’air fortement ventilée (EN ISO 6946, 6.9.4)",
"R<sub>{}</sub> = {} m²K/W ({}, gleichwertig aus R<sub>T</sub> — siehe unten)":"R<sub>{}</sub> = {} m²K/W ({}, équivalent à partir de R<sub>T</sub> — voir ci-dessous)",
"R<sub>{}</sub> = {} m²K/W ({}, d = {} mm, {} — DIN EN ISO 6946, Tab. 8)":"R<sub>{}</sub> = {} m²K/W ({}, d = {} mm, {} — EN ISO 6946, tab. 8)",
"Wärmestrom nach unten":"flux de chaleur descendant",
"Wärmestrom horizontal":"flux de chaleur horizontal",
"Wärmestrom nach oben":"flux de chaleur ascendant",
"R nach Tabelle":"R selon tableau",
"(DIN 4109-32, einschalig massiv)":"(DIN 4109-32, paroi simple massive)",
"Diese Schichten sind durch eine weiche Schicht (ρ < 300 kg/m³) von der massiven Schale getrennt. Das Massegesetz gilt nur für die einschalige Wand; die Wirkung von WDVS oder Vorsatzschalen (ΔR<sub>w</sub> nach DIN 4109-34) ist nicht erfasst.":"Ces couches sont séparées de la paroi massive par une couche souple (ρ < 300 kg/m³). La loi de masse ne vaut que pour la paroi simple ; l’effet d’un ITE ou d’un doublage (ΔR<sub>w</sub> selon DIN 4109-34) n’est pas pris en compte.",
"Nicht angesetzt: {}":"Non pris en compte : {}",
"m′ ≥ 100 kg/m² → R<sub>min</sub> = {} m²K/W (DIN 4108-2, Tab. 3)":"m′ ≥ 100 kg/m² → R<sub>min</sub> = {} m²K/W (DIN 4108-2, tab. 3)",
"m′ < 100 kg/m²: leichtes Bauteil → R<sub>min</sub> = 1,75 m²K/W (DIN 4108-2, 5.1.2.2)":"m′ < 100 kg/m² : élément léger → R<sub>min</sub> = 1,75 m²K/W (DIN 4108-2, 5.1.2.2)",
"Flächenbezogene Masse: leichtes oder schweres Bauteil?":"Masse surfacique : élément léger ou lourd ?",
"Schallschutz: Es zählen d und ρ der massiven Schale (Massegesetz).":"Isolation acoustique : d et ρ de la paroi massive comptent (loi de masse).",
"Tauwasser: Es zählen d, λ (Temperaturverlauf) und μ (Diffusionswiderstand s<sub>d</sub> = μ·d).":"Condensation : d, λ (profil de température) et μ (résistance à la diffusion s<sub>d</sub> = μ·d) comptent.",
"U-Wert: Es zählen d und λ. ρ geht über die flächenbezogene Masse m′ in den Mindestwärmeschutz ein (leichte Bauteile unter 100 kg/m²: R ≥ 1,75 m²K/W).":"Valeur U : d et λ comptent. ρ intervient dans l’isolation minimale via la masse surfacique m′ (éléments légers sous 100 kg/m² : R ≥ 1,75 m²K/W).",
"Die Querkraft ist größer als die Schubtragfähigkeit des Stegs (plastisch oder durch Schubbeulen).":"L’effort tranchant dépasse la résistance au cisaillement de l’âme (plastique ou par voilement).",
"V<sub>Ed</sub> und M<sub>y,Ed</sub> werden im selben Schnitt angesetzt. Beim Einfeldträger liegt max V am Auflager und max M in Feldmitte; wer beide Größtwerte einträgt, liegt auf der sicheren Seite.":"V<sub>Ed</sub> et M<sub>y,Ed</sub> sont pris dans la même section. Pour une poutre sur deux appuis, V max est sur appui et M max à mi-portée ; saisir les deux maxima est du côté de la sécurité.",
"Hinweis zur Lage der Schnittgrößen":"Remarque sur la position des efforts",
