"A<sub>v,z</sub> = A − 2b·t<sub>f</sub> + (t<sub>w</sub> + 2r)·t<sub>f</sub> ≥ η·h<sub>w</sub>·t<sub>w</sub> = {} cm² (η = 1,0, sichere Seite)":"A<sub>v,z</sub> = A − 2b·t<sub>f</sub> + (t<sub>w</sub> + 2r)·t<sub>f</sub> ≥ η·h<sub>w</sub>·t<sub>w</sub> = {} cm² (η = 1,0, du côté de la sécurité)",
