"Fußnote zu Tab. 8.3DE: Bei einem Achsabstand der Stöße ≥ 8Ø und einem Randabstand ≥ 4Ø darf α<sub>6</sub> = 1,0 gesetzt werden (Ø ≥ 16 mm und > 33 % gestoßen: 1,4). Hier nicht angesetzt, also auf der sicheren Seite.":"Note du tableau 8.3DE : avec un entraxe des recouvrements ≥ 8Ø et une distance au bord ≥ 4Ø, on peut prendre α<sub>6</sub> = 1,0 (Ø ≥ 16 mm et > 33 % recouverts : 1,4). Non appliqué ici, donc du côté de la sécurité.",
