"Diese Berechnung stammt aus einer älteren calc-Version ohne gespeicherte Verläufe. Bitte in calc neu berechnen und speichern.":"Ce calcul provient d'une ancienne version de calc sans courbes enregistrées. Veuillez le recalculer dans calc et l'enregistrer.",
"Kragarm: Zugseite oben, das Moment wird als Betrag übernommen. Biegedrillknicken/Kippen rechnet size für gabelgelagerte Träger — Lagerung und Kipplänge prüfen.":"Console : zone tendue en haut, le moment est repris en valeur absolue. size calcule le déversement pour des poutres à appuis à fourche — vérifier les appuis et la longueur de déversement.",
"Feldmoment und Stützmoment sind die Größtwerte über alle Felder; die Stützweite ist die des Feldes mit dem größten Feldmoment. Für Stahl und Holz wird der Momentenverlauf als Gleichlast angesetzt — bitte prüfen.":"Le moment en travée et le moment sur appui sont les valeurs maximales sur toutes les travées ; la portée est celle de la travée présentant le plus grand moment en travée. Pour l'acier et le bois, le diagramme des moments est assimilé à une charge uniforme — à vérifier.",
"Bauphysik rechnet mit dem Bauteilaufbau — aus calc gibt es hier nichts zu übernehmen.":"La physique du bâtiment travaille avec la composition de l'élément — rien à reprendre de calc ici.",
"Wasserbau rechnet mit eigenen Eingaben (Abfluss, Geometrie) — aus calc gibt es hier nichts zu übernehmen.":"L'hydraulique travaille avec ses propres données (débit, géométrie) — rien à reprendre de calc ici.",
"Für die Stütze braucht size eine Normalkraft. Die gibt es nur bei Rahmen-Berechnungen (Stiel). Bitte einen Rahmen wählen oder N<sub>Ed</sub> von Hand eingeben.":"Pour le poteau, size a besoin d'un effort normal. Il n'est fourni que par les calculs de portiques (montant). Veuillez choisir un portique ou saisir N<sub>Ed</sub> manuellement.",
"Kein positives Feldmoment: Das Moment wird als Betrag für M<sub>Ed</sub> übernommen — die Zugbewehrung liegt dann oben.":"Pas de moment positif en travée : le moment est repris en valeur absolue pour M<sub>Ed</sub> — les armatures tendues sont alors en partie haute.",
"M<sub>qp</sub> (quasi-ständig, für die Rissbreite) kennt calc nicht — bitte von Hand eingeben.":"calc ne connaît pas M<sub>qp</sub> (quasi permanent, pour l'ouverture des fissures) — veuillez le saisir manuellement.",
"Platte: Die Werte gelten je Meter Breite, wenn die Lasten in calc je m² eingegeben wurden.":"Dalle : les valeurs s'entendent par mètre de largeur si les charges ont été saisies par m² dans calc.",
"Für den Stützenfuß braucht es eine Normalkraft — nur Rahmen-Berechnungen liefern sie.":"Pour le pied de poteau, un effort normal est nécessaire — seuls les calculs de portiques le fournissent.",
"Für Schweißnähte bitte die Kräfte von Hand eingeben — z. B. M<sub>y,Ed</sub> und V<sub>z,Ed</sub> am Trägerende aus calc für den Fall „Träger an Stirnplatte“.":"Pour les soudures, veuillez saisir les efforts manuellement — p. ex. M<sub>y,Ed</sub> et V<sub>z,Ed</sub> à l'extrémité de la poutre issus de calc pour le cas « Poutre sur platine d'about ».",
"M<sub>y,k</sub> für die Durchbiegung ist charakteristisch — bitte von Hand anpassen.":"M<sub>y,k</sub> pour la flèche est caractéristique — veuillez l'adapter manuellement.",
"Linearer Momentenverlauf: als „konstant“ angesetzt (sichere Seite).":"Diagramme des moments linéaire : pris comme « constant » (côté sécurité).",
"M<sub>G,k</sub> und M<sub>Q,k</sub> für die Durchbiegung sind charakteristisch — bitte von Hand eingeben.":"M<sub>G,k</sub> et M<sub>Q,k</sub> pour la flèche sont caractéristiques — veuillez les saisir manuellement.",
