"a<sub>sf,erf</sub> = v<sub>Ed</sub>·h<sub>f</sub>/(f<sub>yd</sub>·cot θ<sub>f</sub>) = <b>{} cm²/m</b> Querbewehrung in der Platte, je zur Hälfte oben und unten":"a<sub>sf,req</sub> = v<sub>Ed</sub>·h<sub>f</sub>/(f<sub>yd</sub>·cot θ<sub>f</sub>) = <b>{} cm²/m</b> d'armatures transversales dans la dalle, moitié en haut et moitié en bas",
"Die Anschlussbewehrung ist mit der Biegebewehrung der Platte quer zum Unterzug zu überlagern: maßgebend ist der größere Wert aus a<sub>sf</sub> und ½·a<sub>sf</sub> + Plattenbewehrung (6.2.4(5)).":"L'armature de liaison doit être superposée à l'armature de flexion de la dalle transversale à la poutre : la valeur la plus grande entre a<sub>sf</sub> et ½·a<sub>sf</sub> + armatures de la dalle est déterminante (6.2.4(5)).",
