"Verankerungslänge reicht nicht: Haken bzw. Winkelhaken, kleineren Durchmesser oder tieferes Auflager wählen.":"Longueur d'ancrage insuffisante : choisir un crochet ou un coude, un diamètre plus petit ou un appui plus profond.",
"Staffelung":"Décalage des arrêts de barres",
"{} Stäbe: mindestens 2 Stäbe müssen bis zum Auflager laufen — keine Staffelung möglich":"{} barres : au moins 2 barres doivent aller jusqu'à l'appui — décalage impossible",
"Staffelung: {} von {} Stäben enden vor dem Auflager, {} laufen durch":"Décalage : {} barres sur {} s'arrêtent avant l'appui, {} se poursuivent",
"aufnehmbare Kraft der durchlaufenden Stäbe F<sub>Rd,{}</sub> = {}·{}·{}/10³ = {} kN":"résistance des barres prolongées F<sub>Rd,{}</sub> = {}·{}·{}/10³ = {} kN",
"Die durchlaufenden Stäbe decken schon die ganze Zugkraftlinie — die übrigen Stäbe werden nur aus Mindestgründen gebraucht.":"Les barres prolongées couvrent déjà toute la courbe des efforts de traction — les autres barres ne sont nécessaires que pour des raisons de minimum.",
"Rechnerischer Endpunkt E: dort reicht die verschobene Zugkraftlinie gerade noch für die durchlaufenden Stäbe":"Point d'arrêt théorique E : là, la courbe décalée des efforts de traction est tout juste couverte par les barres prolongées",
"x<sub>E</sub> = u − a<sub>l</sub> = {} − {} = <b>{} m</b> vom Auflager":"x<sub>E</sub> = u − a<sub>l</sub> = {} − {} = <b>{} m</b> à partir de l'appui",
"Ab E müssen die endenden Stäbe noch um die Verankerungslänge weitergeführt werden (voll ausgenutzt, σ<sub>sd</sub> = f<sub>yd</sub>)":"À partir de E, les barres arrêtées doivent être prolongées de la longueur d'ancrage (pleinement sollicitées, σ<sub>sd</sub> = f<sub>yd</sub>)",
"l<sub>bd</sub> = max(Ø/4·f<sub>yd</sub>/f<sub>bd</sub>; 10·Ø; 100) = max({}; {}; 100) = <b>{} mm</b> (gerade, guter Verbund)":"l<sub>bd</sub> = max(Ø/4·f<sub>yd</sub>/f<sub>bd</sub> ; 10·Ø ; 100) = max({} ; {} ; 100) = <b>{} mm</b> (droite, bonnes conditions d'adhérence)",
"x<sub>E</sub> − l<sub>bd</sub> = {} m ≤ 0 → die Stäbe reichen ohnehin bis zum Auflager, Staffelung bringt nichts":"x<sub>E</sub> − l<sub>bd</sub> = {} m ≤ 0 → les barres atteignent de toute façon l'appui, le décalage n'apporte rien",
