"Stabende bei x = x<sub>E</sub> − l<sub>bd</sub> = <b>{} m</b> vom Auflager (beidseitig)":"Arrêt de barre en x = x<sub>E</sub> − l<sub>bd</sub> = <b>{} m</b> à partir de l'appui (des deux côtés)",
"Länge der gestaffelten Stäbe ≥ l − 2·{} = <b>{} m</b> → Ersparnis ≈ {} kg Betonstahl":"Longueur des barres décalées ≥ l − 2·{} = <b>{} m</b> → économie ≈ {} kg d'acier d'armature",
"Zugkraftdeckungsbild: die blaue Deckungslinie muss überall über der orangen Zugkraftlinie liegen":"Épure de décalage des efforts de traction : la ligne bleue de résistance doit se situer partout au-dessus de la ligne orange des efforts de traction",
"<span style=\"color:{}\">orange</span>: F<sub>sd</sub> um a<sub>l</sub> verschoben · grau gestrichelt: M/z · <span style=\"color:{}\">blau</span>: aufnehmbare Kraft F<sub>Rd</sub> (zwischen A und E steigt sie über l<sub>bd</sub> an)":"<span style=\"color:{}\">orange</span> : F<sub>sd</sub> décalé de a<sub>l</sub> · gris en tirets : M/z · <span style=\"color:{}\">bleu</span> : résistance F<sub>Rd</sub> (entre A et E, elle croît sur l<sub>bd</sub>)",
"Zugkraftdeckung und Staffelung":"Couverture des efforts de traction et décalage des arrêts",
"Annahme Einfeldträger mit Gleichlast. Mindestens ¼ der Feldbewehrung (hier mindestens 2 Stäbe) ist bis über das Auflager zu führen; die Verankerung dort ist im Nachweis „Verankerung am Endauflager“ enthalten.":"Hypothèse : poutre sur deux appuis sous charge uniforme. Au moins ¼ des armatures de travée (ici au moins 2 barres) doit être prolongé au-delà de l'appui ; l'ancrage correspondant est inclus dans la vérification « Ancrage à l'appui d'extrémité ».",
"Zwang (z. B. Schwinden, Temperatur): zulässige Stahlspannung aus dem Grenzdurchmesser":"Déformation gênée (p. ex. retrait, température) : contrainte admissible de l'acier à partir du diamètre limite",
"Zwang: f<sub>ct,eff</sub> = {} N/mm² · Ø*<sub>s</sub> = Ø·2,9/f<sub>ct,eff</sub> = {} mm":"Déformation gênée : f<sub>ct,eff</sub> = {} N/mm² · Ø*<sub>s</sub> = Ø·2,9/f<sub>ct,eff</sub> = {} mm",
