"Ausklinkung oben (gegenüber dem Auflager)":"Entaille en partie haute (à l'opposé de l'appui)",
"Die einspringende Ecke liegt in der Druckzone — keine Abminderung: k<sub>v</sub> = 1,0":"L'angle rentrant se trouve dans la zone comprimée — pas de réduction : k<sub>v</sub> = 1,0",
