"h ≤ 7 m, höchstens 2 Nutzungseinheiten mit zusammen ≤ 400 m², nicht freistehend":"h ≤ 7 m, au plus 2 unités d'usage totalisant ≤ 400 m², non isolé",
"hochfeuerhemmend: tragende und aussteifende Teile aus brennbaren Baustoffen nur mit brandschutztechnisch wirksamer Bekleidung (MBO § 26) bzw. nach Muster-Holzbaurichtlinie.":"coupe-feu 60 min : éléments porteurs et de contreventement en matériaux combustibles uniquement avec un revêtement efficace vis-à-vis de la sécurité incendie (MBO § 26) ou selon la directive modèle sur la construction bois.",
"im Keller":"au sous-sol",
"keine Anforderung":"aucune exigence",
