"zulässige Restsetzung > 0":"tassement résiduel admissible > 0",
"Ø < 20 mm oder höchstens 25 % der Stäbe gestoßen: die aus anderen Gründen vorhandene Querbewehrung (z. B. Bügel, Verteilerstäbe) genügt.":"Ø < 20 mm ou au plus 25 % des barres en recouvrement : les armatures transversales présentes pour d'autres raisons (p. ex. étriers, barres de répartition) suffisent.",
"Ø ≥ 20 mm und mehr als 25 % gestoßen: Querbewehrung für die Querzugkräfte nachweisen":"Ø ≥ 20 mm et plus de 25 % des barres en recouvrement : vérifier les armatures transversales pour les efforts de traction transversale",
