"(Durchbruch mittig)":"(percement centré)",
"(eine Verbindungsmittelreihe parallel zur Faser)":"(une rangée d'organes d'assemblage parallèle au fil)",
"(in der Dachebene, schwache Achse)":"(dans le plan du toit, axe faible)",
"(rechtwinklig zur Dachfläche, starke Achse)":"(perpendiculairement au toit, axe fort)",
