"Anschluss höher setzen (größeres a), breiter auseinanderziehen (a<sub>r</sub>), größere wirksame Tiefe, Querzugverstärkung (Vollgewindeschrauben) oder einen höheren Träger.":"Placer l'assemblage plus haut (a plus grand), l'écarter davantage (a<sub>r</sub>), augmenter la profondeur efficace, renforcer contre la traction perpendiculaire (vis à filetage total) ou prendre une poutre plus haute.",
