"Liegt das Verbindungsmittel in den oberen 30 % der Höhe (vom beanspruchten Rand aus gesehen weit weg), wird der Querzug sicher abgetragen.":"Si l’organe d’assemblage se situe dans les 30 % supérieurs de la hauteur (loin du bord sollicité), la traction perpendiculaire est reprise en toute sécurité.",
"Länge der oberen Stäbe ab Auflagerachse (Zugkraftlinie verschoben, plus l<sub>bd</sub>)":"Longueur des barres supérieures à partir de l’axe d’appui (courbe des efforts de traction décalée, plus l<sub>bd</sub>)",
