"Stumpfnaht":"Soudure bout à bout",
"Stumpfnähte an Profilen (Stegnaht und Gurtnähte getrennt), unterschiedliche Blechdicken mit Abschrägung, Ermüdung (Kerbfälle), Prüfumfang und Bewertungsgruppen nach DIN EN ISO 5817 sowie T-Stöße mit Kehlnaht-Stumpfnaht-Kombination.":"Soudures bout à bout sur profilés (soudure d’âme et soudures de semelles séparées), épaisseurs de tôle différentes avec chanfrein, fatigue (catégories de détail), étendue des contrôles et niveaux de qualité selon DIN EN ISO 5817 ainsi que les assemblages en T combinant soudure d’angle et soudure bout à bout.",
