"Verstärkte Durchbrüche (innen und außen liegende Verstärkungen), mehrere Durchbrüche (Abstand l<sub>z</sub>), Durchbrüche in Vollholz und in der Nähe von Ausklinkungen sowie die Durchbiegung mit geschwächtem Querschnitt.":"Percements renforcés (renforts intérieurs et extérieurs), plusieurs percements (distance l<sub>z</sub>), percements dans le bois massif et à proximité d’entailles, ainsi que la flèche avec section affaiblie.",
