"Nicht verankerte, im Boden eingespannte Spundwand: Erddruck mit Teilsicherheiten, Einbindetiefe nach Blum mit Zuschlag und größtes Moment. Teilsicherheiten nach DIN 1054, Erddruck nach DIN 4085.":"Rideau de palplanches non ancré, encastré dans le sol : poussée des terres avec coefficients partiels, fiche selon Blum avec majoration et moment maximal. Coefficients partiels selon DIN 1054, poussée des terres selon DIN 4085.",
"Nichtwohngebäude (andere Werte für S<sub>1</sub> und S<sub>2</sub>), mehrere Fassaden und geneigte Fenster (S<sub>4</sub>), die Bedingungen, unter denen der Nachweis entfallen darf, und die thermische Gebäudesimulation.":"Bâtiments non résidentiels (autres valeurs pour S<sub>1</sub> et S<sub>2</sub>), plusieurs façades et fenêtres inclinées (S<sub>4</sub>), conditions dans lesquelles la vérification peut être omise, et simulation thermique dynamique du bâtiment.",
"Normalspannungen":"Contraintes normales",
