"Zwischen den Halterungen greift keine Querlast an: Die Endmomente kommen aus anschließenden Bauteilen, z. B. Durchlaufträger über der Stütze, Rahmenecke oder Kragarm.":"Aucune charge transversale n’agit entre les maintiens : les moments d’extrémité proviennent des éléments adjacents, p. ex. poutre continue sur appui, angle de portique ou console.",
"Gleich große Endmomente: Über die ganze Länge wirkt dasselbe Moment — für das Biegedrillknicken der ungünstigste Fall (C₁ = 1).":"Moments d’extrémité égaux : le même moment agit sur toute la longueur — le cas le plus défavorable pour le déversement (C₁ = 1).",
"Eine Last am Obergurt wirkt beim Kippen zusätzlich destabilisierend, am Untergurt stabilisierend.":"Une charge sur la semelle supérieure est en plus déstabilisante vis-à-vis du déversement ; sur la semelle inférieure, elle est stabilisante.",
"Blau: gedrückter Gurt — er will seitlich ausweichen (Biegedrillknicken); je kürzer der gedrückte Bereich, desto größer C₁.":"Bleu : semelle comprimée — elle tend à se dérober latéralement (déversement) ; plus la zone comprimée est courte, plus C₁ est grand.",
