"<h1>{}</h1>\n    <div class=\"meta\">kragr·size v{} · {} {} · DIN EN 1993-1-1 mit NA</div>\n    <section><h2>Eingaben</h2><table>\n      {}\n      {}\n      {}\n      {}\n      {}\n      {}\n      {}\n      {}\n    </table></section>\n    <section><h2>Profil</h2><div class=\"figure\">{}</div></section>\n    <section><h2>{}</h2><div class=\"figure\">{}</div></section>\n    {}\n      <p class=\"meta\" style=\"margin-top:8px\">I<sub>T</sub> aus Nennmaßen (Herstellerformel mit Ausrundung), Abweichung zu Tabellenwerten bis etwa 3 %. Lernwerkzeug — ersetzt keine geprüfte Statik.</p></section>":"<h1>{}</h1>\n    <div class=\"meta\">kragr·size v{} · {} {} · DIN EN 1993-1-1 avec AN</div>\n    <section><h2>Données</h2><table>\n      {}\n      {}\n      {}\n      {}\n      {}\n      {}\n      {}\n      {}\n    </table></section>\n    <section><h2>Profilé</h2><div class=\"figure\">{}</div></section>\n    <section><h2>{}</h2><div class=\"figure\">{}</div></section>\n    {}\n      <p class=\"meta\" style=\"margin-top:8px\">I<sub>T</sub> déterminé à partir des dimensions nominales (formule du fabricant avec congé de raccordement), écart par rapport aux valeurs des tableaux jusqu'à environ 3 %. Outil pédagogique — ne remplace pas une note de calcul vérifiée.</p></section>",
