"Eine Last am oberen Rand verlängert die wirksame Kipplänge (+ 2h), am unteren Rand verkürzt sie sie (− 0,5h).":"Une charge sur la rive supérieure augmente la longueur efficace de déversement (+ 2h), sur la rive inférieure elle la réduit (− 0,5h).",
